      return { rule: { kind: 'array', items: items.rule }, required };
    }
    default: {
      rejectMisplaced('fields');
      rejectMisplaced('additionalFields');
      rejectMisplaced('items');
      return { rule: { kind: t as PrimitiveKind }, required };
    }
  }
}

